//! 🧪️ Native replay metadata preserves the portable digest oracle and closes private roots at every prefix.
use super::*;
use semio_framework_value::{FromValue,ToValue};
use semio_framework_pack_json::ArtifactCanonicalJsonTree;
#[derive(Default,PartialEq)]struct Delta;
impl ToValue for Delta{fn to_value(&self)->semio_framework_value::DslValue{semio_framework_value::DslValue::Null}}
impl semio_framework_os_spr::DiffAlgebra<()> for Delta{fn is_empty(&self)->bool{true}}
impl semio_framework_os_spr::MutationDiff<()> for Delta{}
struct Operation(bool);
impl ToValue for Operation{fn to_value(&self)->semio_framework_value::DslValue{self.0.to_value()}}
impl FromValue for Operation{fn from_value(value:semio_framework_value::DslValue)->Result<Self,ValueError>{Ok(Self(bool::from_value(value)?))}}
impl ArtifactCanonicalJsonTree for Operation{fn canonical_tree_node(&self)->Result<semio_framework_pack_json::ArtifactCanonicalJsonNode<'_>,ValueError>{self.0.canonical_tree_node()}}
impl Mutation<()> for Operation{type Diff=Delta;const DESCRIPTORS:&'static[semio_framework_os_spr::MutationLeafDescriptor]=&[];fn descriptor(&self)->&'static semio_framework_os_spr::MutationLeafDescriptor{panic!("metadata codec fixture does not execute domain semantics")}}
fn turn()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:32768,maximum_capacity_bytes:16*1024*1024,maximum_release_bytes:16*1024*1024,maximum_depth:4096}}
fn denied(mut grant:RetainedCloneGrant,axis:usize)->RetainedCloneGrant{match axis{0=>grant.maximum_items=0,1=>grant.maximum_copy_bytes=0,2=>grant.maximum_capacity_bytes=0,3=>grant.maximum_release_bytes=0,_=>grant.maximum_depth=0}grant}
fn exact(p:RetainedCloneProgress,heap:semio_framework_trace::HeapAllocationObservation){assert!(p.fits(turn()));assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));}
#[test]fn original_replay_metadata_matches_portable_hash_and_preserves_denied_and_cancelled_sources(){let cases:serde_json::Value=serde_json::from_str(include_str!("../../../🔏️digest/🔣️.json")).unwrap();for case in cases.as_array().unwrap(){for cut in [0,1,16,128,usize::MAX]{let source=serde_json::to_string(&case["edit"]).unwrap();let value=semio_framework_pack_json::from_json_str(&source,semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();let edit=Edit::<Operation>::from_value(value).unwrap();let mut ledger=semio_framework_os_vcs::ArtifactHistoryLedger::new();let key=ledger.try_push(0u8).unwrap();let empty=Default::default();let flags=HistoryFoldIndex::new();let redo=HistoryPageStack::empty();let mut owner=OriginalReplayMetadata::new([7;32]);let mut completed=false;for index in 0..100000{if index==cut{break}let row=||ReplayMetadataRow{ledger_key:key,edit:&edit,inverse:&edit.inverse,supersessions:&empty,flags:&flags,previous_flags:&flags};for axis in [0,1,4]{let before=(owner.ordinal(),owner.phase,owner.operation);let(p,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.advance::<(),Operation>(Some(row()),&redo,denied(turn(),axis),|digest,edit,inverse,grant|digest.advance_with_inverse(edit,inverse,grant),|_|Ok(())).unwrap());exact(p,heap);assert_eq!(p,Default::default());assert_eq!((owner.ordinal(),owner.phase,owner.operation),before);}let row=if owner.ordinal()==0{Some(row())}else{None};let mut admitted=0;let(p,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.advance::<(),Operation>(row,&redo,turn(),|digest,edit,inverse,grant|digest.advance_with_inverse(edit,inverse,grant),|capacity|{admitted+=capacity;Ok(())}).unwrap());exact(p,heap);assert_eq!(admitted,p.retained_capacity_bytes);if owner.prepared(){completed=true;break}assert!(index<99999);}if cut==usize::MAX{assert!(completed);let revision=owner.revision.as_ref().unwrap();let digest=revision.applied[0].edit_digest;let expected:Vec<u8>=case["digest"].as_array().unwrap().iter().map(|byte|byte.as_u64().unwrap()as u8).collect();assert_eq!(digest.as_slice(),expected);assert_eq!(digest,CursorRevisionAccumulator::edit_digest(&edit));assert_eq!(revision.mutation_positions.len(),edit.forwards.len());assert_eq!(owner.cursor.as_ref().unwrap()[0],edit.id);}owner.begin_close();for index in 0..100000{if owner.terminal_is_empty(){break}let d=owner.close_demands(4096).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:turn().maximum_copy_bytes.max(d.copy_bytes),maximum_capacity_bytes:turn().maximum_capacity_bytes.max(d.capacity_bytes),maximum_release_bytes:turn().maximum_release_bytes.max(d.release_bytes),maximum_depth:turn().maximum_depth.max(d.depth)};let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.close_step(grant).unwrap());assert!(step.progress().fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert!(index<99999);}assert!(owner.terminal_is_empty());ledger.pop();while ledger.retained_terminal_slot_count()>0{ledger.retire_terminal_slot(turn()).unwrap();}while !ledger.backing_is_empty(){ledger.release_empty_page(turn()).unwrap();}}}
}
